"""Private frontend schema, generated by ``make build-investigation-api-docs``.

The referenced and dereferenced OpenAPI files are written to
``.artifacts/investigation-api-docs/`` and validated by ``make test-api-docs`` in CI.
They are excluded from the public schema and its downstream publishing workflow.
"""

from typing import Any

from sentry.investigations.endpoints.base import OrganizationInvestigationsBaseEndpoint


def investigation_endpoints(endpoints: Any) -> Any:
    return [
        endpoint
        for endpoint in endpoints
        if issubclass(endpoint[3].view_class, OrganizationInvestigationsBaseEndpoint)
    ]


PRIVATE_SCHEMA_SETTINGS = {
    "TITLE": "Investigation API (private)",
    "DESCRIPTION": "Private frontend API. These operations are not published or supported as public APIs.",
    "APPEND_PATHS": {},
    "APPEND_COMPONENTS": {},
    "PREPROCESSING_HOOKS": ["sentry.investigations.apidocs.investigation_endpoints"],
    "TAGS": [{"name": "Investigations", "description": "Private investigation frontend APIs."}],
}
